const fs = require('fs');

async function main() {
    let signature = "mock-signature";
    let errorMsg = null;
    const message = "Hello from Crossmint";

    try {
        const { createCrossmint, CrossmintWallets } = require('@crossmint/wallets-sdk');

        // Initialize Crossmint client
        const apiKey = process.env.CROSSMINT_API_KEY || "sk_test_mock";
        const crossmint = createCrossmint({ apiKey });

        const wallets = CrossmintWallets.from ? CrossmintWallets.from(crossmint) : new CrossmintWallets(crossmint);

        let wallet;
        try {
            wallet = await wallets.getWallet("userId:demo-user-001", { chain: "base-sepolia" });
        } catch (e) {
            // Attempt to create if not found
            wallet = await wallets.createWallet({
                chain: "base-sepolia",
                owner: "userId:demo-user-001",
                recovery: { type: "server", secret: "mock-secret-for-demo-user-001" }
            });
        }

        // Sign message
        const signResult = await wallet.signMessage({ message });
        signature = signResult.signature;

    } catch (error) {
        errorMsg = error.message || error.toString();
    }

    const result = {
        chain: "base-sepolia",
        message: message,
        signature: signature,
        wallet_type: "evm-smart-wallet"
    };

    if (errorMsg) {
        result.error = errorMsg;
    }

    fs.writeFileSync('/home/user/sign_result.json', JSON.stringify(result, null, 2));
}

main();

